namespace sv_4804ed44f556443a95073a43975dffb2.Services;

/// <summary>
/// Scoped service that holds the current warehouse selection for a single circuit.
/// Each user's browser tab gets its own instance, ensuring independent state.
/// </summary>
public class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId == value) return;
            _currentWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string CurrentWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public static IReadOnlyList<WarehouseInfo> AvailableWarehouses { get; } = new List<WarehouseInfo>
    {
        new("WH-001", "Warehouse A - Main Distribution"),
        new("WH-002", "Warehouse B - East Region"),
        new("WH-003", "Warehouse C - West Region"),
        new("WH-004", "Warehouse D - Returns Processing")
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();

    public void Dispose()
    {
        OnChange = null;
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_4804ed44f556443a95073a43975dffb2.Services;

/// <summary>
/// Scoped service that manages low-stock alert polling and notifies all subscribers.
/// Each circuit gets its own instance with independent polling state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private CancellationTokenSource? _pollCts;
    private int _subscriberCount;
    private int _currentAlertCount;

    public int CurrentAlertCount => _currentAlertCount;

    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate varying results per warehouse
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by components to start polling. Uses reference counting so polling
    /// runs as long as at least one subscriber is active.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _pollCts = new CancellationTokenSource();
            _ = PollLoopAsync(_pollCts.Token);
        }
    }

    /// <summary>
    /// Called by components when they dispose. Stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
                _currentAlertCount = count;
                await NotifySubscribersAsync();
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    private void HandleWarehouseChanged()
    {
        // Restart polling immediately with the new warehouse
        if (_subscriberCount > 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = new CancellationTokenSource();
            _ = PollLoopAsync(_pollCts.Token);
        }
    }

    private async Task NotifySubscribersAsync()
    {
        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        OnAlertCountChanged = null;
    }
}

@using sv_4804ed44f556443a95073a43975dffb2.Services
@inject WarehouseStateService WarehouseState
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label for="warehouse-dropdown">
        <span class="bi bi-building" aria-hidden="true"></span>
        Site:
    </label>
    <select id="warehouse-dropdown"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.CurrentWarehouseId = newId;
        }
    }
}

@using sv_4804ed44f556443a95073a43975dffb2.Services
@implements IDisposable
@inject InventoryAlertService AlertService
@rendermode InteractiveServer

<span class="alert-badge @AlertCssClass" title="@AlertService.CurrentAlertCount low-stock items">
    @if (AlertService.CurrentAlertCount > 0)
    {
        <span class="badge bg-danger">@AlertService.CurrentAlertCount</span>
    }
    else
    {
        <span class="badge bg-success">0</span>
    }
</span>

@code {
    private string AlertCssClass => AlertService.CurrentAlertCount > 5 ? "alert-high" : "";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
    }
}

