@page "/dashboard"
@using sv_4804ed44f556443a95073a43975dffb2.Services
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">
    Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong>
    (@WarehouseState.CurrentWarehouseId)
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentAlertCount > 5 ? "text-danger" : "text-success")">
                    @AlertService.CurrentAlertCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum level
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Warehouse ID</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">Active</p>
                <p class="card-text text-muted">Refreshes every 10s</p>
            </div>
        </div>
    </div>
</div>

<div class="mt-4">
    <small class="text-muted">
        This page starts polling when mounted and stops when you navigate away.
        The sidebar badge also updates from the same polling source.
    </small>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleStateChanged;
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        AlertService.StartPolling();
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleStateChanged;
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        AlertService.StopPolling();
    }
}

